if (Array.isArray(msg.payload)) {
    var length = msg.payload.length;
    if (length > 1) {
        msg.payload = 1;
    } else if (length === 0) {
        msg.payload = 0;
    } else {
        msg.payload = 1;
    }
} else {
    msg.payload = 0;
}
return msg;

// --- 全局配置 ---
// 在此统一设置所有外部服务的地址和参数
// 此节点将在启动时自动运行一次

// Qdrant 向量数据库配置
flow.set('qdrant_host', 'localhost');
flow.set('qdrant_port', '6333');
flow.set('qdrant_api_key', 'face_access_2025');

// Hailo AI芯片 (人脸向量API) 配置
flow.set('hailo_host', '192.168.10.179');
flow.set('hailo_port', '8000');

// Grove Vision AI 摄像头配置
flow.set('image_width', 640);
flow.set('image_height', 480);

// Grove Vision AI 分辨率配置 (AT+RSL=<width>,<height>)
// 支持的分辨率请参考设备文档，例如: '240,240' 或 '480,480'
// 参考: https://github.com/Seeed-Studio/SSCMA-Micro/blob/main/docs/protocol/at-protocol-en_US.md
flow.set('resolution', '640,480');

node.log("Global configuration loaded.");

return msg;

// 读取环境变量或使用默认值
const faceEmbedHost = flow.get('hailo_host') || '192.168.10.179';
const faceEmbedPort = flow.get('hailo_port') || '8000';

// 设置API URL为新的一体化端点
msg.url = `http://${faceEmbedHost}:${faceEmbedPort}/detect_and_embed`;
msg.timeout = 5000; // 设置5秒超时

// 准备请求体，只包含图像
msg.payload = {
    image_base64: msg.payload.img_b64
};

return msg;

// 获取人脸向量
const embedding = msg.payload.vector;
const confidence = msg.payload.confidence;
const processingTime = msg.payload.processing_time_ms;

// 检查向量质量
if (confidence < 0.5) {
    node.warn(`Low face quality: ${confidence}`);
    return null;
}

// 设备与Collection映射配置 - 在此处添加新设备
const deviceCollectionMap = {
    'grove_vision_ai_v2_eb9e4d18': 'office_entrance',
    'grove_vision_ai_v2_002': 'warehouse_door',
    'grove_vision_ai_v2_003': 'lab_access',
    'default': 'default_faces'
};

// 获取设备配置
const deviceId = msg.deviceId;
const collectionName = deviceCollectionMap[deviceId] || deviceCollectionMap['default'];
const threshold = 0.32;  // 相似度阈值，可在此处调整

// 准备Qdrant搜索请求
msg.collectionName = collectionName;
msg.threshold = threshold;
msg.embedding = embedding;
msg.confidence = confidence;
msg.processingTime = processingTime;

// 从Flow上下文中获取Qdrant配置
const qdrantHost = flow.get('qdrant_host') || 'localhost';
const qdrantPort = flow.get('qdrant_port') || '6333';
msg.url = `http://${qdrantHost}:${qdrantPort}/collections/${collectionName}/points/search`;

msg.payload = {
    vector: embedding,
    limit: 3,
    with_payload: true,
    score_threshold: 1 - threshold  // Qdrant使用余弦相似度，需要转换阈值
};

// 设置HTTP请求头
const qdrantApiKey = flow.get('qdrant_api_key');
msg.headers = { 'Content-Type': 'application/json' };
if (qdrantApiKey) {
    msg.headers['api-key'] = qdrantApiKey;
}

return msg;

const searchResult = msg.payload.result;
const deviceId = msg.deviceId;
const threshold = msg.threshold;
const timestamp = new Date().toISOString();

let decision = false;
let name = null;
let distance = 1.0;
let matchedId = null;

// 检查搜索结果
if (searchResult && searchResult.length > 0) {
    node.log(searchResult);
    const bestMatch = searchResult[0];
    distance = 1 - bestMatch.score;  // 转换为距离

    if (distance <= threshold) {
        decision = true;
        name = bestMatch.payload.name;
        matchedId = bestMatch.id;
    }
}

// 构造结果消息
const result = {
    ts: timestamp,
    device_id: deviceId,
    decision: decision,
    name: name,
    distance: parseFloat(distance.toFixed(4)),
    confidence: msg.confidence,
    processing_time_ms: msg.processingTime,
    matched_id: matchedId
};

// 准备MQTT发布
msg.topic = `access/result/${deviceId}`;
msg.payload = result;

// 保存到context用于日志记录
context.set('lastAccess', result);

return msg;

const result = msg.payload;

// 记录访问日志
node.log(`Access Decision - Device: ${result.device_id}, Decision: ${result.decision}, Name: ${result.name || 'Unknown'}, Distance: ${result.distance}`);

// 可以在这里添加更详细的日志记录逻辑
// 例如写入文件、数据库等

return msg;

const payload = msg.payload;
const topic = msg.topic;
const deviceId = topic.split('/')[2];


// 验证入库请求
if (!payload.name || !payload.action || !payload.collection) {
    node.error('Invalid enroll request: missing name, action, or collection');
    return null;
}

if (payload.action === 'start') {
    // 开始入库流程
    msg.deviceId = deviceId;
    msg.enrollName = payload.name;
    msg.payload = {
        action: 'start_collection',
        name: payload.name,
        device_id: deviceId
    };

    // 设置入库状态
    flow.set(`enroll_${deviceId}`, {
        name: payload.name,
        collection: payload.collection, // 存储目标库
        status: 'collecting',
        vectors: [], // 初始化向量数组
        startTime: Date.now()
    });

    return msg;
}

return null;

// 这个节点会监听后续的vision帧来收集人脸数据
// 实际实现中需要与vision_frame_processor协调

const deviceId = msg.deviceId;
const enrollState = context.get(`enroll_${deviceId}`);

if (!enrollState || enrollState.status !== 'collecting') {
    return null;
}

// 发送开始收集的指令
msg.topic = `access/enroll_status/${deviceId}`;
msg.payload = {
    status: 'collecting',
    message: `开始收集 ${enrollState.name} 的人脸数据，请保持正面朝向摄像头`,
    frames_needed: 10
};

return msg;

// 整合Grove Vision AI V2的输出1(图像)和输出2(检测结果)
// 直接组装成标准vision frame格式

const camera_id = msg.camera_id || 'grove_vision_ai_v2_eb9e4d18';

// 判断数据来源：输出1是图像数据(buffer)，输出2是检测结果(array)
if (Buffer.isBuffer(msg.payload) || typeof msg.payload === 'string') {
    // 输出1: 原始图像数据
    context.set(`image_${camera_id}`, {
        img_b64: msg.payload,
        timestamp: Date.now()
    });

    // 图像数据不直接输出，等待检测结果
    return null;

} else if (Array.isArray(msg.payload)) {
    // 输出2: 检测结果 - 组合图像和检测框
    const bboxes = msg.payload;

    // 获取对应的图像数据
    const imageContext = context.get(`image_${camera_id}`);
    if (!imageContext) {
        node.warn('No image data found for camera: ' + camera_id);
        return null;
    }

    // 检查图像数据是否过期（超过3秒）
    if (Date.now() - imageContext.timestamp > 3000) {
        node.warn('Image data too old for camera: ' + camera_id);
        context.set(`image_${camera_id}`, null);
        return null;
    }

    // 转换Grove Vision AI V2的bbox格式到标准格式
    // Grove格式: [x_center, y_center, width, height, confidence, class]
    const convertedBboxes = [];
    if (Array.isArray(bboxes)) {
        for (const bbox of bboxes) {
            if (bbox.length < 5) continue;

            const x_center = bbox[0];
            const y_center = bbox[1];
            const width = bbox[2];
            const height = bbox[3];
            const confidence = bbox[4];

            // 从中心点坐标转换为左上角坐标
            const x_topleft = x_center - width / 2;
            const y_topleft = y_center - height / 2;

            // --- 强制边界框修正逻辑 (已修复浮点误差问题) ---
            const maxImageWidth = flow.get('image_width') || 480;
            const maxImageHeight = flow.get('image_height') || 480;

            // 1. 计算原始的四个浮点数边界
            const left = x_topleft;
            const top = y_topleft;
            const right = x_topleft + width;
            const bottom = y_topleft + height;

            // 2. 将边界限制在图像尺寸内，然后进行整数化，确保安全
            const final_left = Math.round(Math.max(0, left));
            const final_top = Math.round(Math.max(0, top));
            const final_right = Math.round(Math.min(maxImageWidth, right));
            const final_bottom = Math.round(Math.min(maxImageHeight, bottom));

            // 3. 根据修正后的整数边界计算最终的整数 x, y, w, h
            const final_x = final_left;
            const final_y = final_top;
            const final_w = final_right - final_left;
            const final_h = final_bottom - final_top;

            // 4. 再次检查尺寸有效性 (如果裁剪后宽度或高度<=0，则跳过)
            if (final_w <= 0 || final_h <= 0) {
                node.warn(`Bbox has zero size after clipping, skipping. Original: [${bbox.join(', ')}]`);
                continue;
            }

            const score = confidence / 100.0; // 转换为0-1范围

            convertedBboxes.push({
                x: final_x,
                y: final_y,
                w: final_w,
                h: final_h,
                score: score
            });
        }
    }

    const standardPayload = {
        ts: new Date().toISOString(),
        img_b64: imageContext.img_b64,
        bboxes: convertedBboxes
    };

    msg.deviceId = camera_id;
    msg.topic = `vision/frames/${camera_id}`;
    msg.payload = standardPayload;

    context.set(`image_${camera_id}`, null);

    return msg;

} else {
    return null;
}

// 检查 `msg.payload.bboxes` 数组是否存在且不为空
if (msg.payload && Array.isArray(msg.payload.bboxes) && msg.payload.bboxes.length > 0) {
    // 如果有检测结果，则将消息传递给下一个节点
    return msg; 
} else {
    // 如果没有检测到目标，则中止流程，不返回任何消息
    node.warn("未检测到目标，已中止API调用。");
    return null; 
}

// 处理Grove Vision AI V2的检测触发信号
// 可用于统计、日志记录等

const camera_id = msg.camera_id || 'unknown';
const detected = msg.payload;

if (detected) {
    node.log(`Face detected by camera: ${camera_id}`);

    // 更新检测统计
    const stats = context.get('detection_stats') || {};
    const today = new Date().toDateString();

    if (!stats[today]) {
        stats[today] = {};
    }
    if (!stats[today][camera_id]) {
        stats[today][camera_id] = 0;
    }

    stats[today][camera_id]++;
    context.set('detection_stats', stats);
}

return null;  // 不继续传递消息

const results = msg.payload;

// 检查API是否返回了有效的人脸数组
if (!Array.isArray(results) || results.length === 0) {
    // 如果没有检测到人脸，则终止流程
    return null; 
}

let largestFace = null;
let maxArea = 0;

for (const face of results) {
    const bbox = face.bbox;

    // 修正：检查bbox是否为包含x,y,w,h的对象
    if (bbox && typeof bbox.x === 'number' && typeof bbox.y === 'number' && typeof bbox.w === 'number' && typeof bbox.h === 'number') {
        const area = bbox.w * bbox.h;
        if (area > maxArea) {
            maxArea = area;
            largestFace = face;
        }
    } else {
        node.warn(`收到的bbox格式不正确: ${JSON.stringify(bbox)}`);
    }
}

if (!largestFace) {
    node.warn("检测到的人脸数据中没有有效的边界框。");
    return null;
}

// 修正：正确地从API响应中提取嵌套的数据
const newMsg = {
    ...msg,
    payload: {
        embedding: largestFace.embedding.vector,
        bbox: largestFace.bbox,
        landmarks: largestFace.landmarks,
        // 准备给下一个节点的数据
        vector: largestFace.embedding.vector,
        confidence: largestFace.embedding.confidence,
        processing_time_ms: largestFace.embedding.processing_time_ms,
        detection_confidence: largestFace.detection_confidence
    },
    originalImage: msg.originalImage || msg.payload.image_base64
};

// 根据上下文判断是识别流程还是入库流程
const deviceId = msg.deviceId;
const enrollState = flow.get('enroll_' + deviceId);

if (enrollState && enrollState.status === 'collecting') {
    return [null, newMsg];
} else {
    return [newMsg, null];
}

const deviceId = msg.deviceId;
const enrollState = flow.get('enroll_' + deviceId);

if (!enrollState || enrollState.status !== 'collecting') {
    node.warn('Not in collecting state, ignoring vector.');
    return null;
}

// 1. 收集向量
const vector = msg.payload.vector;
if (vector) {
    enrollState.vectors.push(vector);
}
flow.set('enroll_' + deviceId, enrollState);

const collectedCount = enrollState.vectors.length;
const neededCount = 10;

// 2. 发送进度更新
const statusUpdate = {
    topic: `access/enroll_status/${deviceId}`,
    payload: {
        status: 'collecting',
        message: `正在收集人脸数据... (${collectedCount}/${neededCount})`,
        collected: collectedCount,
        needed: neededCount
    }
};

// 如果还没收集满，只发送进度，然后停止
if (collectedCount < neededCount) {
    return [statusUpdate, null];
}

// --- 如果收集完成，开始处理 --- 
node.log(`Collected ${neededCount} vectors for ${enrollState.name}. Averaging and preparing...`);
enrollState.status = 'saving';
flow.set('enroll_' + deviceId, enrollState);

// 3. 计算平均向量
const vectors = enrollState.vectors;
const vectorDim = vectors[0].length;
const avgVector = new Array(vectorDim).fill(0);

for (const v of vectors) {
    for (let i = 0; i < vectorDim; i++) {
        avgVector[i] += v[i];
    }
}
for (let i = 0; i < vectorDim; i++) {
    avgVector[i] /= vectors.length;
}

// 4. 准备Qdrant Collection创建和Point入库
const qdrantHost = flow.get('qdrant_host') || 'localhost';
const qdrantPort = flow.get('qdrant_port') || '6333';
const collectionName = enrollState.collection;

if (!collectionName) {
    node.error(`Enrollment for ${enrollState.name} failed: Collection name not found in context.`);
    const errorMsg = {
        topic: `access/enroll_status/${deviceId}`,
        payload: { status: 'error', message: '入库失败: 未指定目标数据库(collection)。' }
    };
    flow.set('enroll_' + deviceId, null); // 清理状态
    return [errorMsg, null]; // 发送错误并停止
}

// 生成一个随机UUID作为Point ID
const pointId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
});

// **将入库数据存到消息中，供后续节点使用**
msg.qdrantPoint = {
    points: [
        {
            id: pointId,
            vector: avgVector,
            payload: { name: enrollState.name }
        }
    ]
};
msg.collectionName = collectionName;
// 继承deviceId等信息
const qdrantChainMsg = { ...msg };

// **准备创建Collection的请求**
qdrantChainMsg.url = `http://${qdrantHost}:${qdrantPort}/collections/${collectionName}`;//注意这里没有/points
qdrantChainMsg.method = 'PUT';
qdrantChainMsg.payload = {
    vectors: {
        size: 512, // ArcFace model produces 512-d vectors
        distance: "Cosine"
    }
};

// 设置HTTP请求头
const qdrantApiKey = flow.get('qdrant_api_key');
qdrantChainMsg.headers = { 'Content-Type': 'application/json' };
if (qdrantApiKey) {
    qdrantChainMsg.headers['api-key'] = qdrantApiKey;
}

const finalStatusUpdate = {
    topic: `access/enroll_status/${deviceId}`,
    payload: {
        status: 'saving',
        message: '数据收集完成，正在创建集合并存入数据库...'
    }
};

// 输出1: MQTT状态更新
// 输出2: Qdrant创建集合的请求
return [finalStatusUpdate, qdrantChainMsg];

const qdrantHost = flow.get('qdrant_host') || 'localhost';
const qdrantPort = flow.get('qdrant_port') || '6333';

// 从上一个节点的消息中获取入库数据和集合名称
const pointPayload = msg.qdrantPoint;
const collectionName = msg.collectionName;

// 检查上一个节点（创建集合）是否出错
// Qdrant的PUT /collections/{name}在成功或已存在时都返回200 OK
// 因此，任何其他状态码都表示一个需要注意的问题。
if (msg.statusCode && msg.statusCode !== 200) {
    node.error(`Failed to create or verify collection '${collectionName}'. Status: ${msg.statusCode}, Payload: ${JSON.stringify(msg.payload)}`);
    // 错误将传递给下一个节点，并由 入库最终状态 节点处理
}

msg.url = `http://${qdrantHost}:${qdrantPort}/collections/${collectionName}/points?wait=true`;
msg.method = 'PUT';
msg.payload = pointPayload;

// 设置HTTP请求头
const qdrantApiKey = flow.get('qdrant_api_key');
msg.headers = { 'Content-Type': 'application/json' };
if (qdrantApiKey) {
    msg.headers['api-key'] = qdrantApiKey;
}

return msg;

const deviceId = msg.deviceId;
const enrollState = flow.get('enroll_' + deviceId);
let finalMessage;
if (msg.statusCode === 200 && msg.payload.status === 'ok') {
    finalMessage = {
        status: 'success',
        message: `用户 ${enrollState.name} 人脸入库成功!`
    };
    node.log(`Enrollment success for ${enrollState.name}.`);
} else {
    finalMessage = {
        status: 'error',
        message: `用户 ${enrollState.name} 人脸入库失败: ${msg.payload.status.error}`
    };
    node.error(`Enrollment failed: ${JSON.stringify(msg.payload)}`);
}

// 清理上下文
flow.set('enroll_' + deviceId, null);

msg.topic = `access/enroll_status/${deviceId}`;
msg.payload = finalMessage;

return msg;

// 从全局配置中获取分辨率字符串，例如 '240,240' 或 '480,480'
const resolution = flow.get('resolution') || '240,240';
// 从触发器消息中获取设备ID
const deviceId = msg.topic || 'grove_vision_ai_v2_eb9e4d18';

// --- 分辨率到OPT_ID的映射 ---
// !!重要!!: 此映射是基于通用实践的推断，您需要根据完整的设备文档来确认正确的OPT_ID
// AT+SENSOR=<SENSOR_ID,ENABLE/DISABLE,OPT_ID>\r
// 参考: https://github.com/Seeed-Studio/SSCMA-Micro/blob/main/docs/protocol/at-protocol-en_US.md
const resolutionMap = {
    '240,240': 0, // 假设 OPT_ID 0 是 240x240
    '480,480': 1,  // 假设 OPT_ID 1 是 480x480 (需要验证)
    '640,480': 2
};

const opt_id = resolutionMap[resolution];
if (typeof opt_id === 'undefined') {
    node.error(`不支持的分辨率配置: ${resolution}`);
    return null;
}

// 构造用于发送AT指令的MQTT主题
const commandTopic = `sscma/v0/${deviceId}/rx`;

// 构造设置传感器的AT指令 (sensor_id=1, enable=1)
const atCommand = `AT+SENSOR=1,1,${opt_id}\r\n`;

node.log(`准备发送指令到 ${commandTopic}: ${atCommand}`);

msg.topic = commandTopic;
// 将字符串指令转换为设备需要的Buffer格式
msg.payload = Buffer.from(atCommand);

return msg;

// 从输入中获取 collection 和 name
const collection = msg.payload.collection;
const nameToDelete = msg.payload.name;

if (!collection || !nameToDelete) {
    node.error("删除失败：必须在输入中提供 'collection' 和 'name'", msg);
    return null;
}

// 从Flow上下文中获取Qdrant配置
const qdrantHost = flow.get('qdrant_host') || 'localhost';
const qdrantPort = flow.get('qdrant_port') || '6333';

// 设置Qdrant删除点的API端点
msg.url = `http://${qdrantHost}:${qdrantPort}/collections/${collection}/points/delete`;

// Qdrant的删除操作是POST请求
msg.method = 'POST';

// 构建删除过滤器
msg.payload = {
    "filter": {
        "must": [
            {
                "key": "name",
                "match": {
                    "value": nameToDelete
                }
            }
        ]
    }
};

// 设置HTTP请求头
const qdrantApiKey = flow.get('qdrant_api_key');
msg.headers = { 'Content-Type': 'application/json' };
if (qdrantApiKey) {
    msg.headers['api-key'] = qdrantApiKey;
}

node.log(`准备从'${collection}'中删除名为'${nameToDelete}'的数据`);

return msg;

function getJpegSize(buffer) {
    let i = 2; // Skip the JPEG header (0xFFD8)
    while (i < buffer.length) {
        if (buffer[i] !== 0xFF) {
            break;
        }

        const marker = buffer[i + 1];
        const length = buffer.readUInt16BE(i + 2);

        // Start Of Frame markers (not all SOF markers, but common ones)
        if (marker === 0xC0 || marker === 0xC2) {
            const height = buffer.readUInt16BE(i + 5);
            const width = buffer.readUInt16BE(i + 7);
            return { width, height };
        }

        i += 2 + length;
    }
    return null;
}

// Step 1: 解析 base64 为 Buffer
const base64 = msg.payload.replace(/^data:image\/\w+;base64,/, '');
const buffer = Buffer.from(base64, 'base64');

// Step 2: 获取尺寸
const size = getJpegSize(buffer);
if (size) {
    msg.payload = size;
} else {
    msg.payload = { error: "无法解析 JPEG 尺寸" };
}
return msg;
